bitset<B+10> ntp;
void init(){
    for(int i=2;i<=n;i++){
        if(!nt[i]) p.eb(i);
        for(int j:p){
            if(i*j>n)   break;
            nt[i*j]=true;
            if(i%j==0)  break;
        }
    }
}
ll beg;
void init(ll l,ll r){
    ntp.reset();
    for(ll i=l;i<=n&&i<=r;i++)if(nt[i])ntp[i-beg]=nt[i];
    l=max(l,(ll)n+1);
    for(int i:p)
        for(ll j=max((ll)i,(l+i-1)/i);i*j<=r;j++)   ntp[i*j-beg]=true;
}
inline ll g(ll l,ll r){
    ll res=0;l--;
    beg=l;init(l,r);
    ll L=l;while((L+4)%4!=3)L--;
    for(ll i=L+4;i<=r;i+=4)res+=!ntp[i-beg];
    beg=l/4;init(l/4,r/4);
    L=l/4;while((L+2)%2!=1)L--;
    for(ll i=L+2;i<=r/4;i+=2)res+=!ntp[i-beg];
    beg=l/16;init(l/16,r/16);
    L=l/16;while((L+2)%2!=1)L--;
    for(ll i=L+2;i<=r/16;i+=2)res+=!ntp[i-beg];
    return res;
}
ll g(ll x){
    ll id=(x-1)/B;
    ll res=accumulate(a+1,a+id+1,0ll);
    return res+g(id*B+1,x);
}
